"""Seed the demo (SRS section 10, "E2E anomaly simulation"): 20 normal vehicles + 1 anomaly vehicle, through the public API.

* The 21 plates are REAL Israeli registrations (random sample of the public registry); their profile always comes live from data.gov.il.
* The maintenance records and the inspection results written here are DEMONSTRATION DATA, generated by this script and labelled "[DEMO]" in the
  description / notes. They are not real histories of those vehicles.
* The anomaly vehicle (SRS: 60,000 km and no brake service) must trip the brake maintenance rule. It is a RULE flag, not an ML probability.

Usage:  python scripts/seed_demo.py [http://localhost:8000]
"""
import json
import os
import random
import sys
import time
from datetime import date, timedelta
from pathlib import Path

import httpx

API = sys.argv[1] if len(sys.argv) > 1 else "http://localhost:8000"
PLATES = json.loads((Path(__file__).parent / "demo_plates.json").read_text(encoding="utf-8"))
ANOMALY_INDEX = 0
rng = random.Random(2026)
today = date.today()


def write_key() -> str:
    """Workshop key from the RECORDS_WRITE_KEY environment variable or from the git-ignored .env (never printed)."""
    key = os.environ.get("RECORDS_WRITE_KEY", "")
    env = Path(__file__).resolve().parents[1] / ".env"
    if not key and env.exists():
        for line in env.read_text(encoding="utf-8").splitlines():
            if line.startswith("RECORDS_WRITE_KEY="):
                key = line.split("=", 1)[1].strip()
    if not key:
        sys.exit("RECORDS_WRITE_KEY is not set (environment or .env): the API refuses to write records without it.")
    return key


KEY = write_key()


def post(client: httpx.Client, path: str, body: dict) -> dict | None:
    for _ in range(3):
        r = client.post(API + path, json=body, headers={"X-Write-Key": KEY})
        if r.status_code == 429:          # rate limit of the API: wait and retry
            time.sleep(int(r.headers.get("Retry-After", "60")))
            continue
        if r.status_code in (201, 409):
            return r.json() if r.status_code == 201 else None
        raise RuntimeError(f"{path}: {r.status_code} {r.text[:200]}")
    raise RuntimeError(f"{path}: rate limited")


def main() -> None:
    summary = []
    with httpx.Client(timeout=60) as c:
        for i, v in enumerate(PLATES):
            plate = v["plate"]
            pred = c.get(f"{API}/api/v1/predict/{plate}")
            if pred.status_code != 200:
                print(f"skip {plate}: {pred.status_code}")
                continue
            p = pred.json()
            est = p["mileage"]["estimated_km"]
            if i == ANOMALY_INDEX:
                # SRS anomaly: 60,000 km with ZERO brake replacements (oil and tyres are on record, brakes are not)
                post(c, f"/api/v1/vehicles/{plate}/maintenance", {"service_date": (today - timedelta(days=150)).isoformat(), "mileage_at_service": 58_000,
                                                                  "description": "[DEMO] Oil and filter change", "maintenance_category": "oil", "total_cost": 420})
                post(c, f"/api/v1/vehicles/{plate}/maintenance", {"service_date": (today - timedelta(days=60)).isoformat(), "mileage_at_service": 60_000,
                                                                  "description": "[DEMO] Tyre rotation", "maintenance_category": "tires", "total_cost": 150})
                summary.append((plate, "ANOMALY: 60,000 km, no brake service"))
                continue
            km = int(est * rng.uniform(0.7, 1.05))
            post(c, f"/api/v1/vehicles/{plate}/maintenance", {"service_date": (today - timedelta(days=rng.randint(40, 300))).isoformat(), "mileage_at_service": km,
                                                              "description": "[DEMO] Oil and filter change", "maintenance_category": "oil", "total_cost": 380})
            if rng.random() < 0.7:
                post(c, f"/api/v1/vehicles/{plate}/maintenance", {"service_date": (today - timedelta(days=rng.randint(100, 700))).isoformat(), "mileage_at_service": int(km * 0.8),
                                                                  "description": "[DEMO] Brake pads replaced", "maintenance_category": "brakes", "total_cost": 900})
            if rng.random() < 0.5:
                post(c, f"/api/v1/vehicles/{plate}/maintenance", {"service_date": (today - timedelta(days=rng.randint(30, 500))).isoformat(), "mileage_at_service": int(km * 0.9),
                                                                  "description": "[DEMO] Tyres replaced", "maintenance_category": "tires", "total_cost": 1800})
            if i % 3 == 0 and v["registry_last_test"]:
                last = v["registry_last_test"][:10]
                post(c, f"/api/v1/vehicles/{plate}/inspections", {"inspection_date": last, "odometer_km": km, "brakes_defect": rng.random() < 0.15, "electrical_defect": rng.random() < 0.25,
                                                                   "engine_defect": rng.random() < 0.05, "other_defect": False, "notes": "[DEMO] generated inspection result"})
                summary.append((plate, "with a [DEMO] inspection result (history variant)"))
            else:
                summary.append((plate, "maintenance records only"))
    print(f"seeded {len(summary)} vehicles through {API}")
    for s in summary:
        print(" ", *s)


if __name__ == "__main__":
    main()
